        for c in range(len(g[0])-1):
            box=[(r+i,c+j) for i in(0,1) for j in(0,1)]
            inc=[p for p in box if p in cl]
            if len(inc)==4: segs.append(('sq',frozenset(box),None))
            if len(inc)==3: segs.append(('L',frozenset(inc),[p for p in box if p not in cl][0]))
    byc={}
    for s in segs:
        for p in s[1]: byc.setdefault(p,[]).append(s)
    sols=[]
    def solve(rem,ch):
        if not rem: sols.append(list(ch)); return
        if len(sols)>500: return
        p=min(rem)
        for s in byc.get(p,[]):
            if s[1]<=rem: solve(rem-s[1],ch+[s])
    solve(cl,[])
    if len(sols)!=1: return None,len(sols)
    out=[[0]*len(g[0]) for _ in g]
    for t,cs,m in sols[0]:
