def gen_segs(cl):
    segs=[]
    boxes=[]
    for r in range(6):
        for c in range(6):
            box=[(r+i,c+j) for i in(0,1) for j in(0,1)]
            if all(p in cl for p in box):
                boxes.append(frozenset(box))
    for b in boxes:
        segs.append(('sq',b,None))
        for m in b: segs.append(('L',b-{m},m))
    return segs
